-- Invitations (ADR 0015, amendment of 2026-11-23, slice 4b): Squadio writes them itself. A role of
-- member or viewer, a status of pending, accepted or canceled, the email trimmed and in lower case,
-- and one pending invitation per email in an organization. The table has been empty until now:
-- the plugin allowed no invitations. Generated by drizzle-kit from src/db/auth-schema.ts.
ALTER TABLE "auth"."invitation" ALTER COLUMN "role" SET NOT NULL;--> statement-breakpoint
CREATE UNIQUE INDEX "invitation_one_pending_per_email" ON "auth"."invitation" USING btree ("organization_id","email") WHERE "auth"."invitation"."status" = 'pending';--> statement-breakpoint
ALTER TABLE "auth"."invitation" ADD CONSTRAINT "invitation_role_check" CHECK ("auth"."invitation"."role" in ('member', 'viewer'));--> statement-breakpoint
ALTER TABLE "auth"."invitation" ADD CONSTRAINT "invitation_status_check" CHECK ("auth"."invitation"."status" in ('pending', 'accepted', 'canceled'));--> statement-breakpoint
ALTER TABLE "auth"."invitation" ADD CONSTRAINT "invitation_email_check" CHECK ("auth"."invitation"."email" = lower(btrim("auth"."invitation"."email")));
